CREATE TYPE "Role" AS ENUM ('ADMIN','PM','DEVELOPER');
CREATE TYPE "TaskStatus" AS ENUM ('TODO','IN_PROGRESS','IN_REVIEW','DONE','OVERDUE');
CREATE TYPE "Priority" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE "ActivityType" AS ENUM ('TASK_STATUS_CHANGED','TASK_OVERDUE','TASK_ASSIGNED','PROJECT_CREATED','TASK_CREATED');
CREATE TYPE "NotificationType" AS ENUM ('TASK_ASSIGNED','TASK_IN_REVIEW');
CREATE TABLE "User"("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY("id"));
CREATE TABLE "RefreshToken"("id" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RefreshToken_pkey" PRIMARY KEY("id"));
CREATE TABLE "Client"("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"company" TEXT,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Client_pkey" PRIMARY KEY("id"));
CREATE TABLE "Project"("id" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"ownerId" TEXT NOT NULL,"clientId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Project_pkey" PRIMARY KEY("id"));
CREATE TABLE "Task"("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"developerId" TEXT NOT NULL,"status" "TaskStatus" NOT NULL DEFAULT 'TODO',"priority" "Priority" NOT NULL DEFAULT 'MEDIUM',"dueDate" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Task_pkey" PRIMARY KEY("id"));
CREATE TABLE "TaskStatusHistory"("id" TEXT NOT NULL,"taskId" TEXT NOT NULL,"fromStatus" "TaskStatus","toStatus" "TaskStatus" NOT NULL,"changedById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TaskStatusHistory_pkey" PRIMARY KEY("id"));
CREATE TABLE "Activity"("id" TEXT NOT NULL,"type" "ActivityType" NOT NULL,"message" TEXT NOT NULL,"projectId" TEXT,"taskId" TEXT,"actorId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Activity_pkey" PRIMARY KEY("id"));
CREATE TABLE "Notification"("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" "NotificationType" NOT NULL,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"taskId" TEXT,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Notification_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");CREATE UNIQUE INDEX "RefreshToken_tokenHash_key" ON "RefreshToken"("tokenHash");
CREATE INDEX "User_role_idx" ON "User"("role");CREATE INDEX "RefreshToken_userId_expiresAt_idx" ON "RefreshToken"("userId","expiresAt");CREATE INDEX "Client_createdById_idx" ON "Client"("createdById");CREATE INDEX "Project_ownerId_createdAt_idx" ON "Project"("ownerId","createdAt");CREATE INDEX "Project_clientId_idx" ON "Project"("clientId");CREATE INDEX "Task_projectId_status_idx" ON "Task"("projectId","status");CREATE INDEX "Task_developerId_status_idx" ON "Task"("developerId","status");CREATE INDEX "Task_priority_dueDate_idx" ON "Task"("priority","dueDate");CREATE INDEX "Task_dueDate_status_idx" ON "Task"("dueDate","status");CREATE INDEX "TaskStatusHistory_taskId_createdAt_idx" ON "TaskStatusHistory"("taskId","createdAt");CREATE INDEX "Activity_projectId_createdAt_idx" ON "Activity"("projectId","createdAt");CREATE INDEX "Activity_taskId_createdAt_idx" ON "Activity"("taskId","createdAt");CREATE INDEX "Activity_createdAt_idx" ON "Activity"("createdAt");CREATE INDEX "Notification_userId_readAt_createdAt_idx" ON "Notification"("userId","readAt","createdAt");
ALTER TABLE "RefreshToken" ADD CONSTRAINT "RefreshToken_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Client" ADD CONSTRAINT "Client_createdById_fkey" FOREIGN KEY("createdById") REFERENCES "User"("id") ON UPDATE CASCADE;ALTER TABLE "Project" ADD CONSTRAINT "Project_ownerId_fkey" FOREIGN KEY("ownerId") REFERENCES "User"("id") ON UPDATE CASCADE;ALTER TABLE "Project" ADD CONSTRAINT "Project_clientId_fkey" FOREIGN KEY("clientId") REFERENCES "Client"("id") ON UPDATE CASCADE;ALTER TABLE "Task" ADD CONSTRAINT "Task_projectId_fkey" FOREIGN KEY("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Task" ADD CONSTRAINT "Task_developerId_fkey" FOREIGN KEY("developerId") REFERENCES "User"("id") ON UPDATE CASCADE;ALTER TABLE "TaskStatusHistory" ADD CONSTRAINT "TaskStatusHistory_taskId_fkey" FOREIGN KEY("taskId") REFERENCES "Task"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "TaskStatusHistory" ADD CONSTRAINT "TaskStatusHistory_changedById_fkey" FOREIGN KEY("changedById") REFERENCES "User"("id") ON UPDATE CASCADE;ALTER TABLE "Activity" ADD CONSTRAINT "Activity_projectId_fkey" FOREIGN KEY("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Activity" ADD CONSTRAINT "Activity_taskId_fkey" FOREIGN KEY("taskId") REFERENCES "Task"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Activity" ADD CONSTRAINT "Activity_actorId_fkey" FOREIGN KEY("actorId") REFERENCES "User"("id") ON UPDATE CASCADE;ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
